(830,	39,	'_builder_0_pretitle',	'field_builder_builder_section_hero_pretitle'),
(831,	39,	'builder_0_editor',	'<p class=\"h1\">Принципова. Прогресивна.\r\nСяюча.</p>\r\nЗірочка* – це українське політичне та культурне медіа, що аналізує та пояснює політичні, економічні, геополітичні та культурні події, а також ідеї, які формують сучасний світ. Пропонуючи глибше розуміння світу як він є – та яким він міг би бути –  ми вносимо сміливі ідеї в громадську дискусію і розпалюємо дебати далеко за межами наших сторінок.'),
(832,	39,	'_builder_0_editor',	'field_builder_builder_section_hero_editor'),
(833,	39,	'builder_0_image',	'33'),
(834,	39,	'_builder_0_image',	'field_builder_builder_section_hero_image'),
(835,	39,	'builder_1_shower',	'0'),
(836,	39,	'_builder_1_shower',	'field_builder_builder_section_about_shower'),
(837,	39,	'builder_1_title',	'Чому Зірочка?'),
