(839,	39,	'builder_1_bg',	'30'),
(840,	39,	'_builder_1_bg',	'field_builder_builder_section_about_bg'),
(841,	39,	'builder_1_editor',	'Нашу назву можна трактувати по-різному: для когось це зірка, що першою осяює вечірнє небо; для когось –  зірка, яка прикрашає особливо складну задачу в шкільному підручнику. Одначе, початково ми взяли цю назву з дитячого фольклору м.Хмельницького. Щоб повністю зануритися в історію створення назви нашого медіа, читайте більше…'),
